
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_blyp35_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_blyp35", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.871092760073247e+00, -2.817798986801421e+00, -2.743165760040869e+00, -2.639871487933676e+00, -2.499307162101195e+00, -2.312604646334391e+00, -2.073032957860901e+00, -1.780188462346844e+00, -1.445060024126455e+00, -1.090182226442168e+00, -7.349592345363818e-01, -4.933352527935037e-01, -4.254532840584998e-01, -3.554958991260790e-01, -2.588658315934066e-01, -1.617701744214888e-01, -9.485573807365072e-02, -6.309976268239247e-02, -3.973124631167101e-02, -2.711984512840702e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


